use clap::Parser;

/// {{name}} - {{description}}
#[derive(Parser, Debug)]
#[command(name = "{{name}}", version, about)]
struct Args {
    /// Name to greet
    #[arg(short, long, default_value = "World")]
    name: String,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();
    println!("Hello, {}! This is {{name}}", args.name);
    Ok(())
}
